import { Router } from "@angular/router";
import { HttpClient } from "@angular/common/http";
import { inject, Injectable } from "@angular/core";
import { environment } from "../../../environments/environment.development";

import { User } from "src/app/store/userStore";
import { authStore } from "../../store/authStore";
import { DialogService } from "../../shared/services/dialog.service";

@Injectable({
  providedIn: "root",
})
export class AuthService {
  private router = inject(Router);
  private http = inject(HttpClient);
  private authStore = inject(authStore);
  private dialogService = inject(DialogService);

  login(data: { username: string; password: string }) {
    this.dialogService.showDialog();
    return this.http
      .post<User>(`${environment.apiUrl}/auth/login`, data)
      .subscribe({
        next: (user: User) => {
          localStorage.setItem("token", user.token);
          this.router.navigate(["/dashboard"]);
          this.authStore.setAuthenticatedUser(user);
        },
        error: () => this.authStore.setAuthState(false),
        complete: () => this.dialogService.hideDialog(),
      });
  }

  login2() {
    console.log("serviceeee");
    return this.http.post<User>(`${environment.apiUrl}/auth/login`, {
      username: "jf",
      password: "123",
    });
  }

  isLogin() {
    if (localStorage.getItem("token") !== null) {
      this.authStore.setAuthState(true);
      this.router.navigate(["/dashboard"]);
    }
  }

  logout() {
    localStorage.removeItem("token");
    this.router.navigate(["/login"]);
  }
}
